import {
    MOCK_DEFAULT_ORGANIZATION_MEMBER,
    MOCK_DEFAULT_USER,
    MOCK_SECOND_BASIC_USER,
    MOCK_SECOND_ORGANIZATION_MEMBER,
} from 'lib/api.mock'

import { membersLogic } from 'scenes/organization/membersLogic'
import { userLogic } from 'scenes/userLogic'

import { initKeaTests } from '~/test/init'

import { getInviteRowError, inviteLogic } from './inviteLogic'

describe('inviteLogic', () => {
    describe('getInviteRowError', () => {
        const memberEmails = new Set(['teammate@example.com', 'me@example.com'])
        const earlierRowEmails = new Set(['repeat@example.com'])

        it.each([
            ['an empty row', '', null],
            ['a new teammate', 'new@example.com', null],
            [
                'an existing member in another case',
                ' Teammate@Example.com ',
                'This person is already a member of this organization',
            ],
            ['the current user, who is also a member', 'ME@example.com', "You can't invite yourself"],
            ['an email repeated from an earlier row', 'Repeat@example.com', 'This email is already in another row'],
        ])('flags %s', (_, targetEmail, expected) => {
            expect(getInviteRowError(targetEmail, 'me@example.com', memberEmails, earlierRowEmails)).toBe(expected)
        })
    })

    describe('submit gate', () => {
        let logic: ReturnType<typeof inviteLogic.build>

        beforeEach(() => {
            initKeaTests()
            logic = inviteLogic()
            logic.mount()
            userLogic.actions.loadUserSuccess(MOCK_DEFAULT_USER)
            membersLogic.actions.loadAllMembersSuccess([
                MOCK_DEFAULT_ORGANIZATION_MEMBER,
                MOCK_SECOND_ORGANIZATION_MEMBER,
            ])
        })

        afterEach(() => {
            logic.unmount()
        })

        it.each([
            ['an existing member', MOCK_SECOND_BASIC_USER.email.toUpperCase(), false],
            ['the current user', MOCK_DEFAULT_USER.email, false],
            ['a new teammate', 'new.person@example.com', true],
        ])('blocks submit only for a row with %s', (_, email, canSubmit) => {
            logic.actions.updateInviteAtIndex({ target_email: email, isValid: true }, 0)

            expect(logic.values.inviteRowErrors[0] === null).toBe(canSubmit)
            expect(logic.values.canSubmit).toBe(canSubmit)
        })

        it('blocks submit when a later row repeats an earlier one', () => {
            logic.actions.updateInviteAtIndex({ target_email: 'new.person@example.com', isValid: true }, 0)
            logic.actions.appendInviteRow()
            logic.actions.updateInviteAtIndex({ target_email: 'New.Person@example.com', isValid: true }, 1)

            expect(logic.values.inviteRowErrors).toEqual([null, 'This email is already in another row'])
            expect(logic.values.canSubmit).toBe(false)
        })
    })
})

