    describe('getInviteRowError', () => {
        const memberEmails = new Set(['teammate@example.com'])

        it.each([
            ['an empty row', '', null],
            ['a new teammate', 'new.person@example.com', null],
            ['an existing member in another case', ' Teammate@Example.com ', 'already a member'],
            ['your own email in another case', 'ME@example.com', "can't invite yourself"],
        ])('flags %s', (_, targetEmail, expected) => {
            const error = getInviteRowError(targetEmail, memberEmails, 'me@example.com')

            if (expected === null) {
                expect(error).toBeNull()
            } else {
                expect(error).toContain(expected)
            }
        })
    })

    describe('submitting a blocked row', () => {
        const bulkInvite = jest.fn(() => [201, []])

        beforeEach(async () => {
            bulkInvite.mockClear()
            useMocks({ post: { '/api/organizations/:organization_id/invites/bulk/': bulkInvite } })
            initKeaTests()
            userLogic().mount()
            await expectLogic(userLogic).toMatchValues({ user: expect.objectContaining({ email: MOCK_DEFAULT_USER.email }) })
        })

        it('keeps the row and sends nothing when the email is your own', async () => {
            const logic = inviteLogic()
            logic.mount()
            logic.actions.updateInviteAtIndex({ target_email: MOCK_DEFAULT_USER.email.toUpperCase(), isValid: true }, 0)

            await expectLogic(logic, () => logic.actions.inviteTeamMembers()).toFinishAllListeners()

            expect(logic.values.canSubmit).toBe(false)
            expect(logic.values.invitesToSend[0].target_email).toEqual(MOCK_DEFAULT_USER.email.toUpperCase())
            expect(logic.values.inviteRowErrors[0]).toContain("can't invite yourself")
            expect(bulkInvite).not.toHaveBeenCalled()
        })
    })
})

